using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Collections.ObjectModel;
using System.Linq;

namespace Discord;

public class Emoji : IEmote
{
	private static IReadOnlyCollection<string> _unicodes;

	private static IReadOnlyDictionary<string, ReadOnlyCollection<string>> _unicodesAndNames;

	public string Name { get; }

	private static IReadOnlyDictionary<string, string> NamesAndUnicodes { get; }

	private static IReadOnlyCollection<string> Unicodes
	{
		get
		{
			if (_unicodes == null)
			{
				_unicodes = NamesAndUnicodes.Select((KeyValuePair<string, string> kvp) => kvp.Value).ToImmutableHashSet();
			}
			return _unicodes;
		}
	}

	private static IReadOnlyDictionary<string, ReadOnlyCollection<string>> UnicodesAndNames
	{
		get
		{
			if (_unicodesAndNames == null)
			{
				_unicodesAndNames = (from kvp in NamesAndUnicodes
					group kvp by kvp.Value).ToImmutableDictionary((IGrouping<string, KeyValuePair<string, string>> grouping) => grouping.Key, (IGrouping<string, KeyValuePair<string, string>> grouping) => grouping.Select((KeyValuePair<string, string> kvp) => kvp.Key).ToList().AsReadOnly());
			}
			return _unicodesAndNames;
		}
	}

	public override string ToString()
	{
		return Name;
	}

	public Emoji(string unicode)
	{
		Name = unicode;
	}

	public override bool Equals(object other)
	{
		if (other == null)
		{
			return false;
		}
		if (other == this)
		{
			return true;
		}
		if (other is Emoji emoji)
		{
			return string.Equals(Name, emoji.Name);
		}
		return false;
	}

	public static bool TryParse(string text, out Emoji result)
	{
		result = null;
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		if (NamesAndUnicodes.ContainsKey(text))
		{
			result = new Emoji(NamesAndUnicodes[text]);
		}
		if (Unicodes.Contains(text))
		{
			result = new Emoji(text);
		}
		return result != null;
	}

	public static Emoji Parse(string emojiStr)
	{
		if (!TryParse(emojiStr, out var result))
		{
			throw new FormatException("String is not emoji name or unicode!");
		}
		return result;
	}

	public override int GetHashCode()
	{
		return Name.GetHashCode();
	}

	public static implicit operator Emoji(string s)
	{
		return Parse(s);
	}

